"""Surgical storefront installer.  Run from the repo root:   python apply_storefront.py
- writes storefront.css (new file)
- in index.html replaces ONLY the storefront section; the chat-widget markup/layout is left exactly as you have it
- swaps the widget's Wrennon logo/name for Northbound Goods (no position changes)"""
import base64, zlib, os, re, sys
BLOCK = zlib.decompress(base64.b64decode("")).decode()
CSS = zlib.decompress(base64.b64decode("")).decode()
MARK = '<svg viewBox="0 0 36 36" width="18" height="18" aria-hidden="true"><circle cx="18" cy="18" r="16" fill="none" stroke="currentColor" stroke-width="2"/><path d="M18 6.5L22.6 18H18Z" fill="currentColor"/><path d="M18 29.5L13.4 18H18Z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="M18 6.5L13.4 18H18Z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg>'
FONT_OLD = "&display=swap"
def patch(path):
    s = open(path, encoding="utf-8").read()
    if "<!-- Northbound Goods" in s:
        a = s.index("  <!-- Northbound Goods"); m = re.search(r"\n[ \t]*<!-- Chat widget -->", s[a:])
        if not m: sys.exit("Chat widget comment not found in " + path)
        b = a + m.start() + 1
    elif "<!-- Placeholder storefront" in s:
        a = s.index("  <!-- Placeholder storefront"); b = s.index("</main>", a) + len("</main>\n")
    else:
        sys.exit("Could not find the storefront section in " + path)
    s = s[:a] + BLOCK + s[b:]
    s = re.sub(r'\n?<link rel="stylesheet" href="storefront\.css[^"]*">', "", s)
    s = re.sub(r'(<link rel="stylesheet" href="ui-polish\.css[^"]*">)', r'\1\n<link rel="stylesheet" href="storefront.css?v=4">', s, count=1)
    s = re.sub(r"<title>[^<]*</title>", "<title>Northbound Goods \u2014 Outerwear, Footwear, Essentials &amp; Accessories</title>", s, count=1)
    if "family=Jost" not in s: s = s.replace(FONT_OLD, "&family=Jost:wght@400;500;600" + FONT_OLD, 1)
    n1 = 1
    s = s.replace("Wrennon Agent", "Northbound Support").replace('aria-label="Wrennon customer support chat"', 'aria-label="Northbound Goods customer support chat"')
    open(path, "w", encoding="utf-8").write(s)
    mh = re.search(r'<header id="panel-header".*?</header>', s, re.S)  # DIAG
    print("widget header markup found:", "yes" if mh else "NO (send me your widget header HTML)")
    print("updated:", path, "| widget branding applied via CSS")
ok = False
for t in ("frontend", os.path.join("backend", "app", "static")):
    if os.path.isdir(t) and os.path.exists(os.path.join(t, "index.html")):
        patch(os.path.join(t, "index.html"))
        open(os.path.join(t, "storefront.css"), "w", encoding="utf-8").write(CSS); print("written:", os.path.join(t, "storefront.css")); ok = True
if not ok: sys.exit("Run from the repo root (folder containing 'frontend' and 'backend').")
print("Done. Hard-refresh the browser (Ctrl+Shift+R).")
